import Link from 'next/link'
import { ArrowLeft, ChevronRight } from 'lucide-react'
import { cn } from '@/lib/utils'
import {
  Breadcrumb,
  BreadcrumbItem,
  BreadcrumbLink,
  BreadcrumbList,
  BreadcrumbPage,
  BreadcrumbSeparator,
} from '@/components/ui/breadcrumb'

interface BreadcrumbItemDef {
  label: string
  href?: string // absent = current page (not a link)
}

interface PageHeaderProps {
  title: string
  description?: string         // replaces old `subtitle`
  actions?: React.ReactNode    // replaces old `right`
  breadcrumb?: BreadcrumbItemDef[]
  backHref?: string            // renders a back button/link before title
  className?: string
}

export function PageHeader({
  title,
  description,
  actions,
  breadcrumb,
  backHref,
  className,
}: PageHeaderProps) {
  return (
    <div
      className={cn(
        'relative flex flex-col gap-1 sm:flex-row sm:items-start sm:justify-between',
        // Hairline rust divider — brand signature under the title row.
        // Short 40px stripe at left, fades out; adds visual rhythm without a full border.
        "after:pointer-events-none after:absolute after:-bottom-4 after:left-0 after:h-px after:w-10 after:bg-[linear-gradient(to_right,_oklch(58%_0.16_35/_0.6),_transparent)]",
        'mb-4',
        className,
      )}
    >
      {/* Left column */}
      <div className="flex flex-col gap-1 min-w-0">
        {/* Back link */}
        {backHref && (
          <Link
            href={backHref}
            className="inline-flex items-center gap-1.5 text-sm text-muted-foreground hover:text-foreground transition-colors mb-1"
          >
            <ArrowLeft className="size-3.5" aria-hidden="true" />
            Back
          </Link>
        )}

        {/* Breadcrumb */}
        {breadcrumb && breadcrumb.length > 0 && (
          <Breadcrumb className="mb-2">
            <BreadcrumbList className="text-[13px]">
              {breadcrumb.map((item, i) => {
                const isLast = i === breadcrumb.length - 1
                return (
                  <BreadcrumbItem key={i}>
                    {isLast ? (
                      <BreadcrumbPage className="text-[13px]">{item.label}</BreadcrumbPage>
                    ) : (
                      <>
                        <BreadcrumbLink
                          render={<Link href={item.href ?? '#'} className="text-[13px]" />}
                        >
                          {item.label}
                        </BreadcrumbLink>
                        <BreadcrumbSeparator>
                          <ChevronRight className="size-3" aria-hidden="true" />
                        </BreadcrumbSeparator>
                      </>
                    )}
                  </BreadcrumbItem>
                )
              })}
            </BreadcrumbList>
          </Breadcrumb>
        )}

        {/* Title — Instrument Serif per brand book */}
        <h1 className="font-display text-[36px] leading-[1.1] text-foreground truncate">
          {title}
        </h1>

        {/* Description */}
        {description && (
          <p className="text-sm text-stone-brand mt-1.5">
            {description}
          </p>
        )}
      </div>

      {/* Actions slot */}
      {actions && (
        <div className="flex shrink-0 items-center gap-2 mt-4 sm:mt-0">
          {actions}
        </div>
      )}
    </div>
  )
}

import type { ReactNode } from 'react'
import { cn } from '@/lib/utils'

interface PageShellProps {
  children: ReactNode
  /**
   * Opt out of default padding for full-height layouts (Calendar, Messages).
   * The page is responsible for its own scroll container + internal padding.
   */
  fullHeight?: boolean
  /** Max content width cap. Default `1440`. Pass `false` to disable the cap. */
  maxWidth?: number | false
  /** Extra classes applied to the outer wrapper. */
  className?: string
  /** Extra classes applied to the inner padded container (ignored when fullHeight). */
  innerClassName?: string
}

/**
 * S18 — Branded page container.
 *
 * Enforces the same gutter + vertical rhythm the TodayClient established as the
 * gold standard: `px-4 sm:px-6 lg:px-8 pt-6 pb-10`, `max-w-[1440px]` cap,
 * background token `--color-page-bg`. Every authenticated page should wrap its
 * content in `<PageShell>`. Full-height layouts (Calendar, Messages) pass
 * `fullHeight` to skip the default padding and handle scroll internally.
 */
export function PageShell({
  children,
  fullHeight = false,
  maxWidth = 1440,
  className,
  innerClassName,
}: PageShellProps) {
  if (fullHeight) {
    return (
      <div className={cn('flex min-h-0 flex-1 flex-col', className)}>
        {children}
      </div>
    )
  }

  return (
    <div
      className={cn(
        // Base page background + dark-aware radial highlight (top-right) + rust
        // whisper (bottom-left). Both tokens flip between light (bone highlight,
        // faint rust) and dark (subtle rust warmth, slightly stronger rust) so
        // the page keeps tonal depth in either theme without blowing out.
        'relative flex min-h-full flex-col bg-[var(--color-page-bg)]',
        'before:pointer-events-none before:absolute before:inset-0',
        'before:bg-[radial-gradient(ellipse_at_top_right,_var(--color-page-highlight)_0%,_transparent_55%)]',
        'after:pointer-events-none after:absolute after:inset-0',
        'after:bg-[radial-gradient(circle_at_bottom_left,_var(--color-page-whisper)_0%,_transparent_45%)]',
        className,
      )}
    >
      <div
        style={
          maxWidth !== false && maxWidth !== 1440
            ? { maxWidth: `${maxWidth}px` }
            : undefined
        }
        className={cn(
          'relative z-10 mx-auto w-full flex-1 px-4 pb-10 pt-6 sm:px-6 lg:px-8',
          maxWidth === 1440 && 'max-w-[1440px]',
          innerClassName,
        )}
      >
        {children}
      </div>
    </div>
  )
}

import type { Metadata } from 'next'
import { redirect } from 'next/navigation'
import { Suspense } from 'react'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { PageShell } from '@/components/shared/PageShell'
import { PageHeader } from '@/components/shared/PageHeader'
import { ClientsPageClient } from './ClientsPageClient'
import type { ClientTag } from '@/components/clients/TagChip'

export const metadata: Metadata = {
  title: 'Clients — InkOS',
}

export default async function ClientsPage() {
  const auth = await getAuthenticatedUser()
  if (!auth) redirect('/login')

  const supabase = await createClient()

  // S23 audit v1 — Clients page is the client list only. Tags moved to
  // /settings/tags, Consent Forms live in the sidebar, AI Design lives on
  // the individual client profile (or /ai-design).
  const [clientsResult, tagsResult] = await Promise.all([
    supabase
      .from('clients')
      .select('id, studio_id, first_name, last_name, email, phone, tags, total_spent_cents, total_sessions, last_visit_at, no_show_count, source, preferred_contact, archived_at, created_at, updated_at, date_of_birth, address, notes, referral_source, cancellation_count, loyalty_points, lifetime_value_cents, avg_session_value_cents, consent_minor, instagram_handle, tiktok_handle, website_url, is_banned, banned_reason, banned_at, banned_by, pronouns, avatar_url')
      .eq('studio_id', auth.studioId)
      .is('archived_at', null)
      .order('last_visit_at', { ascending: false, nullsFirst: false })
      .limit(50),
    supabase
      .from('client_tags')
      .select('id, name, color, icon')
      .eq('studio_id', auth.studioId)
      .order('name'),
  ])
  const initialClients = clientsResult.data ?? []
  const tagLibrary = (tagsResult.data ?? []) as ClientTag[]

  return (
    <PageShell>
      <PageHeader
        title="Clients"
        description="Manage client profiles, history, and notes."
      />

      <Suspense fallback={<div className="flex-1 animate-pulse bg-muted/20 m-6 rounded-xl" />}>
        <ClientsPageClient
          initialClients={initialClients}
          tagLibrary={tagLibrary}
        />
      </Suspense>
    </PageShell>
  )
}

'use client'

import { useRef } from 'react'
import { useRouter, usePathname } from 'next/navigation'
import { cn } from '@/lib/utils'
import { PlanBadge } from '@/components/shared/PlanBadge'
import { PLAN_ORDER } from '@/lib/billing/feature-gate'
import type { PlanTier } from '@/lib/billing/feature-gate'
import type { NavRole } from '@/components/app/sidebar/nav-config'

export interface PageTab {
  key: string
  label: string
  href: string
  badge?: number | string
  gated?: PlanTier
  /** Return true to hide this tab for the given role */
  hidden?: (role: NavRole) => boolean
}

export interface PageTabsProps {
  tabs: PageTab[]
  activeKey: string
  currentPlan: PlanTier
  currentRole: NavRole
  className?: string
}

/**
 * S13 — Horizontal underline tab row with URL persistence via ?tab= query param.
 *
 * Accessibility:
 *  - role="tablist" on container
 *  - role="tab" + aria-selected on each trigger
 *  - Arrow key navigation within the tab row (ARIA authoring practices)
 *  - focus-visible ring on each trigger
 *
 * URL persistence:
 *  - Active tab read from ?tab= param by parent; defaulted to tabs[0].key if absent/invalid
 *  - Navigates via router.replace({pathname}?tab={key}, { scroll: false }) — no full reload
 *
 * Plan gating:
 *  - If tab.gated is set and user plan is below requirement, renders tab at reduced opacity
 *  - Click on gated tab routes to /settings/billing
 */
export function PageTabs({ tabs, activeKey, currentPlan, currentRole, className }: PageTabsProps) {
  const router = useRouter()
  const pathname = usePathname()
  const listRef = useRef<HTMLDivElement>(null)

  const visibleTabs = tabs.filter((t) => !(t.hidden?.(currentRole) ?? false))

  function isLocked(tab: PageTab): boolean {
    return tab.gated != null && PLAN_ORDER[currentPlan] < PLAN_ORDER[tab.gated]
  }

  function handleSelect(tab: PageTab) {
    if (isLocked(tab)) {
      router.push('/settings/billing')
      return
    }
    router.replace(`${pathname}?tab=${tab.key}`, { scroll: false })
  }

  function handleKeyDown(e: React.KeyboardEvent<HTMLButtonElement>, currentIndex: number) {
    const triggers = listRef.current?.querySelectorAll<HTMLButtonElement>('[role="tab"]')
    if (!triggers) return

    let nextIndex: number | null = null

    if (e.key === 'ArrowRight') {
      nextIndex = (currentIndex + 1) % triggers.length
    } else if (e.key === 'ArrowLeft') {
      nextIndex = (currentIndex - 1 + triggers.length) % triggers.length
    } else if (e.key === 'Home') {
      nextIndex = 0
    } else if (e.key === 'End') {
      nextIndex = triggers.length - 1
    }

    if (nextIndex !== null) {
      e.preventDefault()
      triggers[nextIndex]?.focus()
    }
  }

  return (
    <div
      ref={listRef}
      role="tablist"
      aria-label="Page sections"
      className={cn(
        'flex items-end gap-0 border-b border-border/60',
        'overflow-x-auto scrollbar-none',
        // Fade edges on mobile only
        '[mask-image:linear-gradient(to_right,transparent_0px,black_16px,black_calc(100%-16px),transparent_100%)]',
        'md:[mask-image:none]',
        className,
      )}
    >
      {visibleTabs.map((tab, index) => {
        const isActive = tab.key === activeKey
        const locked = isLocked(tab)

        return (
          <button
            key={tab.key}
            type="button"
            role="tab"
            aria-selected={isActive}
            onClick={() => handleSelect(tab)}
            onKeyDown={(e) => handleKeyDown(e, index)}
            className={cn(
              'relative flex items-center gap-1.5 px-3 h-10 shrink-0',
              'text-sm whitespace-nowrap transition-colors duration-150',
              'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-0',
              isActive
                ? [
                    'font-semibold text-foreground',
                    'after:absolute after:bottom-0 after:inset-x-0 after:h-0.5 after:bg-primary after:rounded-full',
                  ]
                : 'font-medium text-muted-foreground hover:text-foreground',
              locked && 'opacity-60 cursor-default',
            )}
          >
            {tab.label}
            {tab.gated != null && <PlanBadge plan={tab.gated} />}
            {tab.badge != null && (
              <span className="inline-flex items-center rounded-full bg-muted text-muted-foreground text-[10px] font-semibold leading-none px-1.5 py-0.5 min-w-[18px] justify-center tabular-nums">
                {tab.badge}
              </span>
            )}
          </button>
        )
      })}
    </div>
  )
}

'use client'

import { useRef } from 'react'
import { Search, Star, AlertTriangle, X, Tag, UserCircle, Clock, Columns3, Stethoscope, MoreHorizontal, Archive } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Badge } from '@/components/ui/badge'
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from '@/components/ui/popover'
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu'
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from '@/components/ui/command'
import { Checkbox } from '@/components/ui/checkbox'
import { type ClientTag } from './TagChip'
import { cn } from '@/lib/utils'

export interface ClientFilters {
  q: string
  tags: string[]
  vip: boolean
  inactive: boolean
  noShows: boolean
  showArchived: boolean
  hasAlerts: boolean
  spendingTier: '' | '0-500' | '500-2000' | '2000-5000' | '5000+'
  artistIds: string[]
  serviceIds: string[]
  lastVisitRange: '' | '30d' | '90d' | '90d+' | 'never'
}

export interface FilterArtist {
  id: string
  display_name: string
}

export interface FilterService {
  id: string
  name: string
}

interface ClientFilterBarProps {
  filters: ClientFilters
  onChange: (filters: ClientFilters) => void
  tagLibrary: ClientTag[]
  artists?: FilterArtist[]
  services?: FilterService[]
}

const SPENDING_OPTIONS: { value: ClientFilters['spendingTier']; label: string }[] = [
  { value: '', label: 'Any' },
  { value: '0-500', label: '$0 – $500' },
  { value: '500-2000', label: '$500 – $2K' },
  { value: '2000-5000', label: '$2K – $5K' },
  { value: '5000+', label: '$5K+' },
]

const LAST_VISIT_OPTIONS: { value: ClientFilters['lastVisitRange']; label: string }[] = [
  { value: '', label: 'Any time' },
  { value: '30d', label: 'Last 30 days' },
  { value: '90d', label: 'Last 90 days' },
  { value: '90d+', label: '90+ days ago (inactive)' },
  { value: 'never', label: 'Never visited' },
]

export function ClientFilterBar({
  filters,
  onChange,
  tagLibrary,
  artists = [],
  services = [],
}: ClientFilterBarProps) {
  const searchRef = useRef<HTMLInputElement>(null)
  const debounceRef = useRef<ReturnType<typeof setTimeout> | null>(null)

  function set<K extends keyof ClientFilters>(key: K, value: ClientFilters[K]) {
    onChange({ ...filters, [key]: value })
  }

  function handleSearchChange(e: React.ChangeEvent<HTMLInputElement>) {
    const val = e.target.value
    if (debounceRef.current) clearTimeout(debounceRef.current)
    debounceRef.current = setTimeout(() => {
      set('q', val)
    }, 150)
  }

  function toggleTag(slug: string) {
    const next = filters.tags.includes(slug)
      ? filters.tags.filter((t) => t !== slug)
      : [...filters.tags, slug]
    set('tags', next)
  }

  function toggleArtist(id: string) {
    const next = filters.artistIds.includes(id)
      ? filters.artistIds.filter((a) => a !== id)
      : [...filters.artistIds, id]
    set('artistIds', next)
  }

  function toggleService(id: string) {
    const next = filters.serviceIds.includes(id)
      ? filters.serviceIds.filter((s) => s !== id)
      : [...filters.serviceIds, id]
    set('serviceIds', next)
  }

  function clearAll() {
    onChange({
      q: '',
      tags: [],
      vip: false,
      inactive: false,
      noShows: false,
      showArchived: false,
      hasAlerts: false,
      spendingTier: '',
      artistIds: [],
      serviceIds: [],
      lastVisitRange: '',
    })
    if (searchRef.current) searchRef.current.value = ''
  }

  const hasActiveFilters = Boolean(
    filters.q ||
    filters.tags.length > 0 ||
    filters.vip ||
    filters.noShows ||
    filters.hasAlerts ||
    filters.spendingTier ||
    filters.artistIds.length > 0 ||
    filters.serviceIds.length > 0 ||
    filters.lastVisitRange
  )

  const activeChips: { label: string; onRemove: () => void }[] = []
  if (filters.vip) activeChips.push({ label: 'VIP', onRemove: () => set('vip', false) })
  if (filters.noShows) activeChips.push({ label: 'No-shows', onRemove: () => set('noShows', false) })
  if (filters.hasAlerts) activeChips.push({ label: 'Has alerts', onRemove: () => set('hasAlerts', false) })
  if (filters.spendingTier) {
    const label = SPENDING_OPTIONS.find((o) => o.value === filters.spendingTier)?.label ?? filters.spendingTier
    activeChips.push({ label: `VIP: ${label}`, onRemove: () => set('spendingTier', '') })
  }
  if (filters.lastVisitRange) {
    const label = LAST_VISIT_OPTIONS.find((o) => o.value === filters.lastVisitRange)?.label ?? filters.lastVisitRange
    activeChips.push({ label: `Visit: ${label}`, onRemove: () => set('lastVisitRange', '') })
  }
  for (const slug of filters.tags) {
    const tag = tagLibrary.find((t) => t.name === slug || t.id === slug)
    activeChips.push({ label: tag?.name ?? slug, onRemove: () => toggleTag(slug) })
  }
  for (const id of filters.artistIds) {
    const artist = artists.find((a) => a.id === id)
    activeChips.push({ label: `Artist: ${artist?.display_name ?? id}`, onRemove: () => toggleArtist(id) })
  }
  for (const id of filters.serviceIds) {
    const service = services.find((s) => s.id === id)
    activeChips.push({ label: `Service: ${service?.name ?? id}`, onRemove: () => toggleService(id) })
  }

  return (
    <div className="flex flex-col gap-3">
      {/* Search + filter controls */}
      <div className="flex flex-wrap items-center gap-2">
        {/* Search */}
        <div className="relative max-w-sm w-full sm:w-auto">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-3.5 w-3.5 text-muted-foreground pointer-events-none" />
          <Input
            ref={searchRef}
            defaultValue={filters.q}
            onChange={handleSearchChange}
            placeholder="Search clients…"
            className="h-9 pl-9 text-sm max-w-sm"
          />
        </div>

        {/* Tag filter */}
        <Popover>
          <PopoverTrigger render={
            <Button
              variant="outline"
              size="sm"
              className={cn(
                'h-9 gap-1.5',
                filters.tags.length > 0 && 'bg-primary/10 border-primary/20 text-primary'
              )}
            >
              <Tag className="h-3.5 w-3.5" aria-hidden="true" />
              {filters.tags.length > 0 ? `${filters.tags.length} tags` : 'Tags'}
            </Button>
          } />
          <PopoverContent className="w-[240px] p-0" align="start">
            {tagLibrary.length === 0 ? (
              <div className="p-4 text-center space-y-2">
                <p className="text-sm font-medium text-foreground">No tags yet</p>
                <p className="text-xs text-stone-brand">
                  Create tags like VIP or Allergic in Settings to filter clients faster.
                </p>
                <Button
                  size="sm"
                  variant="outline"
                  className="w-full h-8 text-xs"
                  onClick={() => {
                    window.location.href = '/settings/tags'
                  }}
                >
                  Go to Settings → Tags
                </Button>
              </div>
            ) : (
              <Command>
                <CommandInput placeholder="Search tags…" className="h-9" />
                <CommandList>
                  <CommandEmpty>No tags match</CommandEmpty>
                  <CommandGroup>
                    {tagLibrary.map((tag) => (
                      <CommandItem
                        key={tag.id}
                        onSelect={() => toggleTag(tag.id)}
                        className="flex items-center gap-2"
                      >
                        <Checkbox
                          checked={filters.tags.includes(tag.id)}
                          className="pointer-events-none"
                          aria-hidden
                        />
                        <span className={cn('h-2 w-2 rounded-full shrink-0', `tag-chip-${tag.color}`)} />
                        <span className="flex-1 text-sm">{tag.name}</span>
                      </CommandItem>
                    ))}
                  </CommandGroup>
                  {filters.tags.length > 0 && (
                    <div className="border-t border-border/40 p-1">
                      <Button variant="ghost" size="sm" className="w-full h-7 text-xs" onClick={() => set('tags', [])}>
                        Clear tags
                      </Button>
                    </div>
                  )}
                </CommandList>
              </Command>
            )}
          </PopoverContent>
        </Popover>

        {/* Artist facet */}
        {artists.length > 0 && (
          <Popover>
            <PopoverTrigger render={
              <Button
                variant="outline"
                size="sm"
                className={cn(
                  'h-9 gap-1.5',
                  filters.artistIds.length > 0 && 'bg-primary/10 border-primary/20 text-primary'
                )}
              >
                <UserCircle className="h-3.5 w-3.5" aria-hidden="true" />
                {filters.artistIds.length > 0 ? `${filters.artistIds.length} artist${filters.artistIds.length !== 1 ? 's' : ''}` : 'Artist'}
              </Button>
            } />
            <PopoverContent className="w-[220px] p-0" align="start">
              <Command>
                <CommandInput placeholder="Search artists…" className="h-9" />
                <CommandList>
                  <CommandEmpty>No artists found</CommandEmpty>
                  <CommandGroup>
                    {artists.map((artist) => (
                      <CommandItem
                        key={artist.id}
                        onSelect={() => toggleArtist(artist.id)}
                        className="flex items-center gap-2"
                      >
                        <Checkbox
                          checked={filters.artistIds.includes(artist.id)}
                          className="pointer-events-none"
                          aria-hidden
                        />
                        <span className="flex-1 text-sm">{artist.display_name}</span>
                      </CommandItem>
                    ))}
                  </CommandGroup>
                  {filters.artistIds.length > 0 && (
                    <div className="border-t border-border/40 p-1">
                      <Button variant="ghost" size="sm" className="w-full h-7 text-xs" onClick={() => set('artistIds', [])}>
                        Clear
                      </Button>
                    </div>
                  )}
                </CommandList>
              </Command>
            </PopoverContent>
          </Popover>
        )}

        {/* Service facet */}
        {services.length > 0 && (
          <Popover>
            <PopoverTrigger render={
              <Button
                variant="outline"
                size="sm"
                className={cn(
                  'h-9 gap-1.5',
                  filters.serviceIds.length > 0 && 'bg-primary/10 border-primary/20 text-primary'
                )}
              >
                <Tag className="h-3.5 w-3.5" aria-hidden="true" />
                {filters.serviceIds.length > 0 ? `${filters.serviceIds.length} service${filters.serviceIds.length !== 1 ? 's' : ''}` : 'Service'}
              </Button>
            } />
            <PopoverContent className="w-[220px] p-0" align="start">
              <Command>
                <CommandInput placeholder="Search services…" className="h-9" />
                <CommandList>
                  <CommandEmpty>No services found</CommandEmpty>
                  <CommandGroup>
                    {services.map((service) => (
                      <CommandItem
                        key={service.id}
                        onSelect={() => toggleService(service.id)}
                        className="flex items-center gap-2"
                      >
                        <Checkbox
                          checked={filters.serviceIds.includes(service.id)}
                          className="pointer-events-none"
                          aria-hidden
                        />
                        <span className="flex-1 text-sm">{service.name}</span>
                      </CommandItem>
                    ))}
                  </CommandGroup>
                  {filters.serviceIds.length > 0 && (
                    <div className="border-t border-border/40 p-1">
                      <Button variant="ghost" size="sm" className="w-full h-7 text-xs" onClick={() => set('serviceIds', [])}>
                        Clear
                      </Button>
                    </div>
                  )}
                </CommandList>
              </Command>
            </PopoverContent>
          </Popover>
        )}

        {/* VIP filter — 5 spending tiers (replaces former vip toggle + separate LTV filter per Clients Audit v1) */}
        <Popover>
          <PopoverTrigger render={
            <Button
              variant="outline"
              size="sm"
              className={cn('h-9 gap-1.5', filters.spendingTier && 'bg-primary/10 border-primary/20 text-primary')}
            >
              <Star className="h-3.5 w-3.5" aria-hidden="true" />
              VIP
              {filters.spendingTier && (
                <span className="ml-1 text-xs opacity-70">
                  {SPENDING_OPTIONS.find((o) => o.value === filters.spendingTier)?.label}
                </span>
              )}
            </Button>
          } />
          <PopoverContent className="w-[200px] p-1" align="start">
            <div className="space-y-0.5">
              {SPENDING_OPTIONS.map((opt) => (
                <button
                  key={opt.value || '__any'}
                  type="button"
                  className={cn(
                    'w-full text-left text-sm px-2.5 py-1.5 rounded-md hover:bg-muted transition-colors',
                    filters.spendingTier === opt.value && 'bg-primary/10 text-primary'
                  )}
                  onClick={() => set('spendingTier', opt.value)}
                >
                  {opt.label}
                </button>
              ))}
            </div>
          </PopoverContent>
        </Popover>

        {/* Last visit range */}
        <Popover>
          <PopoverTrigger render={
            <Button
              variant="outline"
              size="sm"
              className={cn('h-9 gap-1.5', filters.lastVisitRange && 'bg-primary/10 border-primary/20 text-primary')}
            >
              <Clock className="h-3.5 w-3.5" aria-hidden="true" />
              {filters.lastVisitRange
                ? LAST_VISIT_OPTIONS.find((o) => o.value === filters.lastVisitRange)?.label ?? 'Last visit'
                : 'Last visit'}
            </Button>
          } />
          <PopoverContent className="w-[200px] p-1" align="start">
            <div className="space-y-0.5">
              {LAST_VISIT_OPTIONS.map((opt) => (
                <button
                  key={opt.value || '__any'}
                  type="button"
                  className={cn(
                    'w-full text-left text-sm px-2.5 py-1.5 rounded-md hover:bg-muted transition-colors',
                    filters.lastVisitRange === opt.value && 'bg-primary/10 text-primary'
                  )}
                  onClick={() => set('lastVisitRange', opt.value)}
                >
                  {opt.label}
                </button>
              ))}
            </div>
          </PopoverContent>
        </Popover>

        {/* No-shows toggle */}
        <Button
          variant="outline"
          size="sm"
          className={cn(
            'h-9 gap-1.5',
            filters.noShows && 'bg-destructive/10 border-destructive/20 text-destructive'
          )}
          onClick={() => set('noShows', !filters.noShows)}
        >
          <AlertTriangle className="h-3.5 w-3.5" aria-hidden="true" />
          No-shows
        </Button>

        {/* Has allergy/medical alerts toggle */}
        <Button
          variant="outline"
          size="sm"
          className={cn(
            'h-9 gap-1.5',
            filters.hasAlerts && 'bg-destructive/10 border-destructive/20 text-destructive'
          )}
          onClick={() => set('hasAlerts', !filters.hasAlerts)}
        >
          <Stethoscope className="h-3.5 w-3.5" aria-hidden="true" />
          Has alerts
        </Button>

        {/* Column toggle placeholder — wired in ClientsPageClient */}
        <div className="ml-auto flex items-center gap-2">
          <Button
            id="column-toggle-trigger"
            variant="outline"
            size="sm"
            className="h-9 gap-1.5"
            aria-label="Configure columns"
          >
            <Columns3 className="h-3.5 w-3.5" aria-hidden="true" />
            <span className="hidden sm:inline">Columns</span>
          </Button>

          {/* More actions — Archived toggle + (future) export / import live here
              to keep the main toolbar focused on the everyday filters. */}
          <DropdownMenu>
            <DropdownMenuTrigger
              render={
                <Button
                  variant="outline"
                  size="sm"
                  className="h-9 w-9 p-0"
                  aria-label="More filter options"
                >
                  <MoreHorizontal className="h-4 w-4" aria-hidden="true" />
                </Button>
              }
            />
            <DropdownMenuContent align="end">
              <DropdownMenuItem
                onClick={() => set('showArchived', !filters.showArchived)}
                className="gap-2 text-xs"
              >
                <Archive className="h-3.5 w-3.5" aria-hidden="true" />
                {filters.showArchived ? 'Hide archived clients' : 'Show archived clients'}
              </DropdownMenuItem>
            </DropdownMenuContent>
          </DropdownMenu>
        </div>
      </div>

      {/* Active filter chips */}
      {hasActiveFilters && activeChips.length > 0 && (
        <div className="flex flex-wrap items-center gap-1.5">
          {activeChips.map((chip) => (
            <Badge
              key={chip.label}
              variant="secondary"
              className="h-6 px-2.5 text-xs gap-1.5 cursor-pointer hover:opacity-80 pr-1"
              onClick={chip.onRemove}
            >
              {chip.label}
              <X className="h-3 w-3" aria-hidden="true" />
            </Badge>
          ))}
          <Button variant="ghost" size="sm" className="h-6 text-xs" onClick={clearAll}>
            Clear all
          </Button>
        </div>
      )}
    </div>
  )
}

