import type { ReactNode } from 'react'
import { cn } from '@/lib/utils'

interface PageToolbarProps {
  /** Search input. Grows to max-w-sm; wraps on narrow viewports. */
  search?: ReactNode
  /** Filter chips / facet buttons. Sit after the search input. */
  filters?: ReactNode
  /**
   * Right-aligned meta — record count, last-synced timestamp, etc.
   * Pushed right via `ml-auto`.
   */
  meta?: ReactNode
  /**
   * Right-aligned tools after meta — columns picker, sort picker, export,
   * overflow menu. Compact icon-buttons preferred.
   */
  tools?: ReactNode
  /**
   * Optional second row — active filter chips, bulk-action banner, unsaved-
   * changes alert. Renders beneath the primary row with `gap-2`.
   */
  children?: ReactNode
  className?: string
}

/**
 * S24 — Canonical filter toolbar zone. Shopify-admin "index filters"
 * equivalent. Sits between `<PageViews>` and the content (table / grid).
 *
 * Structure:
 *  Row 1: [search] [filter chips]                    [meta] [tools]
 *  Row 2 (optional children): [active chips | banner | bulk-actions]
 *
 * No background, no border — lives on the Bone surface. Pages compose their
 * existing filter primitives (ClientFilterBar rows, AppointmentFilterBar,
 * etc.) inside the slots without bespoke outer wrappers.
 *
 * Vertical rhythm to neighbors is owned by `<PageShell>`'s `space-y-6`.
 */
export function PageToolbar({
  search,
  filters,
  meta,
  tools,
  children,
  className,
}: PageToolbarProps) {
  const hasPrimaryRow =
    search != null || filters != null || meta != null || tools != null

  return (
    <div className={cn('flex flex-col gap-2', className)}>
      {hasPrimaryRow && (
        <div className="flex flex-wrap items-center gap-2">
          {search != null && (
            <div className="flex w-full sm:w-auto sm:max-w-sm sm:flex-1">
              {search}
            </div>
          )}

          {filters != null && (
            <div className="flex flex-wrap items-center gap-2">{filters}</div>
          )}

          {(meta != null || tools != null) && (
            <div className="ml-auto flex items-center gap-2">
              {meta != null && (
                <span className="flex items-center text-xs text-muted-foreground tabular-nums whitespace-nowrap">
                  {meta}
                </span>
              )}
              {tools}
            </div>
          )}
        </div>
      )}

      {children}
    </div>
  )
}

