import type { Metadata } from 'next'
import { redirect } from 'next/navigation'
import { Suspense } from 'react'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { PageTabs } from '@/components/shared/PageTabs'
import { filterTabsForRole } from '@/components/shared/page-tabs-utils'
import { AppointmentsPageClient } from './_components/AppointmentsPageClient'
import { WaitlistPageClient } from '../waitlist/_components/WaitlistPageClient'
import type { PageTab } from '@/components/shared/PageTabs'
import type { PlanTier } from '@/lib/billing/feature-gate'
import type { NavRole } from '@/components/app/sidebar/nav-config'
import { PageShell } from '@/components/shared/PageShell'
import { PageHeader } from '@/components/shared/PageHeader'
import { Button } from '@/components/ui/button'
import Link from 'next/link'
import { Plus } from 'lucide-react'

export const metadata: Metadata = {
  title: 'Appointments — InkOS',
}

const APPOINTMENTS_TABS: PageTab[] = [
  {
    key: 'list',
    label: 'All',
    href: '/appointments?tab=list',
  },
  {
    key: 'today',
    label: 'Today',
    href: '/appointments?tab=today',
  },
  {
    key: 'waitlist',
    label: 'Waitlist',
    href: '/appointments?tab=waitlist',
    hidden: (role) =>
      role !== 'owner' && role !== 'admin' && role !== 'receptionist',
  },
]

const VALID_KEYS = new Set(APPOINTMENTS_TABS.map((t) => t.key))

interface Props {
  searchParams: Promise<Record<string, string | string[] | undefined>>
}

export default async function AppointmentsPage({ searchParams }: Props) {
  const auth = await getAuthenticatedUser()
  if (!auth) redirect('/login')

  const supabase = await createClient()
  let plan: PlanTier = 'solo'
  const { data: sub } = await supabase
    .from('subscriptions')
    .select('plan_tier')
    .eq('studio_id', auth.studioId)
    .eq('status', 'active')
    .maybeSingle()
  if (sub?.plan_tier) plan = sub.plan_tier as PlanTier

  const role = auth.role as NavRole
  const params = await searchParams
  const rawTab = typeof params.tab === 'string' ? params.tab : undefined
  const activeKey = rawTab && VALID_KEYS.has(rawTab) ? rawTab : 'list'

  return (
    <PageShell>
      <PageHeader
        title="Appointments"
        description="Manage all studio bookings"
        actions={
          <Button size="sm" render={<Link href="/appointments/new" />}>
            <Plus className="h-4 w-4" />
            New booking
          </Button>
        }
      />

      {/* Tab row */}
      <div className="mt-6">
        <PageTabs
          tabs={filterTabsForRole(APPOINTMENTS_TABS, role)}
          activeKey={activeKey}
          currentPlan={plan}
          currentRole={role}
        />
      </div>

      {/* Tab content */}
      <div role="tabpanel" id={`tabpanel-${activeKey}`} className="flex flex-col flex-1 min-h-0 mt-2">
        <Suspense fallback={<div className="flex-1 animate-pulse bg-muted/20 rounded-xl min-h-[200px]" />}>
          {activeKey === 'list' && <AppointmentsPageClient />}
