import type { Metadata } from 'next'
import { redirect } from 'next/navigation'
import { Suspense } from 'react'
import { createClient } from '@/lib/supabase/server'
import { getActiveStudio, NoStudioMembershipError } from '@/lib/context/active-studio'
import { PageHeader } from '@/components/shared/PageHeader'
import { PageTabs } from '@/components/shared/PageTabs'
import { filterTabsForRole } from '@/components/shared/page-tabs-utils'
import { Skeleton } from '@/components/ui/skeleton'
import { TransactionsTab } from '@/components/payments/tabs/TransactionsTab'
import { CommissionsTab } from '@/components/payments/tabs/CommissionsTab'
import { PayrollTab } from '@/components/payments/tabs/PayrollTab'
import type { PlanTier } from '@/lib/billing/feature-gate'
import type { NavRole } from '@/components/app/sidebar/nav-config'
import type { PageTab } from '@/components/shared/PageTabs'
import { PageShell } from '@/components/shared/PageShell'

export const metadata: Metadata = {
  title: 'Payments — InkOS',
}

const VALID_TABS = ['transactions', 'commissions', 'payroll'] as const
type TabKey = (typeof VALID_TABS)[number]

interface SearchParams {
  tab?: string
}

function resolveTab(searchParams: SearchParams, role: NavRole): TabKey {
  const requested = searchParams.tab as TabKey | undefined
  if (requested && VALID_TABS.includes(requested)) {
    // Artists can only access commissions tab
    if (role === 'artist' && requested !== 'commissions') {
      return 'commissions'
    }
    return requested
  }
  // Default tab by role
  if (role === 'artist') return 'commissions'
  return 'transactions'
}

const PAYMENT_TABS: PageTab[] = [
  {
    key: 'transactions',
    label: 'Transactions',
    href: '/payments?tab=transactions',
    hidden: (role) => role === 'artist',
  },
  {
    key: 'commissions',
    label: 'Commissions',
    href: '/payments?tab=commissions',
    gated: 'studio',
    hidden: (role) => role === 'receptionist',
  },
  {
    key: 'payroll',
    label: 'Payroll',
    href: '/payments?tab=payroll',
    gated: 'pro',
    hidden: (role) => role === 'artist' || role === 'receptionist',
  },
]

const TabSkeleton = () => (
  <div className="p-6 space-y-4">
    <Skeleton className="h-8 w-32" />
    <Skeleton className="h-4 w-64" />
    <div className="space-y-2">
      {Array.from({ length: 8 }).map((_, i) => (
        <Skeleton key={i} className="h-12 w-full rounded-lg" />
      ))}
    </div>
  </div>
)

export default async function PaymentsPage({
  searchParams,
}: {
  searchParams: Promise<SearchParams>
}) {
  const supabase = await createClient()
  const {
    data: { user },
  } = await supabase.auth.getUser()

  if (!user) redirect('/login')

  let activeStudio: Awaited<ReturnType<typeof getActiveStudio>>
  try {
    activeStudio = await getActiveStudio()
  } catch (err) {
    if (err instanceof NoStudioMembershipError) redirect('/onboarding')
    redirect('/onboarding')
  }

  const { role, plan } = activeStudio
  const resolvedParams = await searchParams
  const activeTab = resolveTab(resolvedParams, role as NavRole)

  return (
    <PageShell>
      <PageHeader
        title="Payments"
        description="Transactions, commissions, and payroll in one place"
      />

      <div className="mt-6">
        <PageTabs
          tabs={filterTabsForRole(PAYMENT_TABS, role as NavRole)}
          activeKey={activeTab}
          currentPlan={plan as PlanTier}
          currentRole={role as NavRole}
          className="mb-0"
        />
      </div>

      <div className="flex-1 mt-0">
        {activeTab === 'transactions' && (
          <Suspense fallback={<TabSkeleton />}>
            <TransactionsTab />
          </Suspense>
        )}
        {activeTab === 'commissions' && (
          <Suspense fallback={<TabSkeleton />}>
            <CommissionsTab />
          </Suspense>
        )}
        {activeTab === 'payroll' && (
          <Suspense fallback={<TabSkeleton />}>
            <PayrollTab />
          </Suspense>
        )}
      </div>
    </PageShell>
  )
}

import type { Metadata } from 'next'
import { redirect } from 'next/navigation'
import { createClient } from '@/lib/supabase/server'
import { getActiveStudio, NoStudioMembershipError } from '@/lib/context/active-studio'
import { CampaignsHub } from '@/components/marketing/CampaignsHub'
import { ReferralDashboard } from '@/components/marketing/ReferralDashboard'
import { PageShell } from '@/components/shared/PageShell'
import { PageHeader } from '@/components/shared/PageHeader'
import { PageTabs } from '@/components/shared/PageTabs'
import { filterTabsForRole } from '@/components/shared/page-tabs-utils'
import type { PageTab } from '@/components/shared/PageTabs'
import type { PlanTier } from '@/lib/billing/feature-gate'
import type { NavRole } from '@/components/app/sidebar/nav-config'
import type { CampaignType, CampaignStatus, CampaignChannel } from '@/lib/supabase/types'

export const metadata: Metadata = {
  title: 'Marketing — InkOS',
}

const MARKETING_TABS: PageTab[] = [
  {
    key: 'campaigns',
    label: 'Campaigns',
    href: '/marketing?tab=campaigns',
  },
  {
    key: 'referrals',
    label: 'Referral program',
    href: '/marketing?tab=referrals',
  },
]

const VALID_TABS = MARKETING_TABS.map((t) => t.key)

interface Props {
  searchParams: Promise<Record<string, string | string[] | undefined>>
}

export default async function MarketingPage({ searchParams }: Props) {
  const supabase = await createClient()

  let activeStudio: Awaited<ReturnType<typeof getActiveStudio>>
  try {
    activeStudio = await getActiveStudio()
  } catch (err) {
    if (err instanceof NoStudioMembershipError) redirect('/onboarding')
    redirect('/onboarding')
  }

  const { studioId, role, plan } = activeStudio
  const canManage = ['owner', 'admin'].includes(role)

  // S18 fix — plan gating removed per product direction. Sidebar STUDIO pill is
  // the only visual cue; marketing pages render for every plan. S19 will add
  // contextual upsell inside features (e.g., send-cap warning, referral quota).

  type RawCampaign = {
    id: string
    name: string
    type: string
    channel: string
    status: string
    sent_count: number
    open_count: number
    click_count: number
    scheduled_at: string | null
    sent_at: string | null
  }

  const [campaignsResult, referralCodesResult, clientsResult] = await Promise.all([
    supabase
      .from('marketing_campaigns')
      .select('id, name, type, channel, status, sent_count, open_count, click_count, scheduled_at, sent_at')
      .eq('studio_id', studioId)
      .order('created_at', { ascending: false }),
    supabase
      .from('referral_codes')
      .select(`
        id, code, discount_type, discount_value, uses_count, max_uses, is_active,
        client:clients(id, first_name, last_name, email)
      `)
      .eq('studio_id', studioId)
      .order('created_at', { ascending: false }),
    canManage
      ? supabase
          .from('clients')
          .select('id, first_name, last_name, email')
          .eq('studio_id', studioId)
          .is('archived_at', null)
          .order('first_name')
          .limit(200)
      : Promise.resolve({ data: [] }),
  ])

  const campaigns = ((campaignsResult.data ?? []) as unknown as RawCampaign[]).map((c) => ({
    id: c.id,
    name: c.name,
    type: c.type as CampaignType,
    channel: c.channel as CampaignChannel,
    status: c.status as CampaignStatus,
    sent_count: c.sent_count,
    open_count: c.open_count,
    click_count: c.click_count,
    scheduled_at: c.scheduled_at,
    sent_at: c.sent_at,
  }))

  type RawCode = {
    id: string
    code: string
    discount_type: string
    discount_value: number
    uses_count: number
    max_uses: number | null
    is_active: boolean
    client: { id: string; first_name: string; last_name: string; email: string } | null
  }

  const referralCodes = ((referralCodesResult.data ?? []) as unknown as RawCode[]).map((c) => ({
    id: c.id,
    code: c.code,
    discount_type: c.discount_type as 'percentage' | 'fixed',
    discount_value: c.discount_value,
    uses_count: c.uses_count,
    max_uses: c.max_uses,
    is_active: c.is_active,
    client: c.client,
  }))

  const clientOptions = (clientsResult.data ?? []).map((c) => ({
    id: c.id,
    display: `${c.first_name} ${c.last_name} (${c.email})`,
  }))

  const totalReferrals = referralCodes.length
  const totalRedemptions = referralCodes.reduce((sum, c) => sum + c.uses_count, 0)
  const topReferrers = referralCodes.filter((c) => c.uses_count > 0).length

  const params = await searchParams
  const rawTab = typeof params.tab === 'string' ? params.tab : undefined
  const activeKey = rawTab && VALID_TABS.includes(rawTab) ? rawTab : 'campaigns'

  return (
    <PageShell>
      <PageHeader
        title="Marketing"
        description="Campaigns, waitlist, and audience"
      />

      <div className="mt-6">
        <PageTabs
          tabs={filterTabsForRole(MARKETING_TABS, role as NavRole)}
          activeKey={activeKey}
          currentPlan={plan as PlanTier}
          currentRole={role as NavRole}
        />
      </div>

      <div role="tabpanel" id={`tabpanel-${activeKey}`} className="mt-4">
        {activeKey === 'campaigns' && (
          <CampaignsHub campaigns={campaigns} canManage={canManage} />
        )}
        {activeKey === 'referrals' && (
          <ReferralDashboard
            codes={referralCodes}
            totalReferrals={totalReferrals}
            totalRedemptions={totalRedemptions}
            topReferrers={topReferrers}
            clientOptions={clientOptions}
            canManage={canManage}
          />
        )}
      </div>
    </PageShell>
  )
}

