          <Suspense fallback={<TabSkeleton />}>
            <CommissionsTab />
          </Suspense>
        )}
        {activeTab === 'payroll' && (
          <Suspense fallback={<TabSkeleton />}>
            <PayrollTab />
          </Suspense>
        )}
      </div>
    </PageShell>
  )
}

