import { LeaderboardCard } from '@/components/artists/LeaderboardCard'
import type { PageTab } from '@/components/shared/PageTabs'
import type { PlanTier } from '@/lib/billing/feature-gate'
import type { NavRole } from '@/components/app/sidebar/nav-config'
import { PageShell } from '@/components/shared/PageShell'
import { PageHeader } from '@/components/shared/PageHeader'

export const metadata: Metadata = {
  title: 'Team — InkOS',
}

const ARTISTS_TABS: PageTab[] = [
  {
    key: 'roster',
    label: 'Roster',
    href: '/artists?tab=roster',
  },
  {
    key: 'schedules',
    label: 'Schedules',
    href: '/artists?tab=schedules',
    hidden: (role) => role === 'guest_artist',
  },
  {
    key: 'guest-artists',
    label: 'Guest Artists',
    href: '/artists?tab=guest-artists',
    gated: 'pro',
    hidden: (role) => role !== 'owner' && role !== 'admin',
  },
  {
    key: 'permissions',
    label: 'Permissions',
    href: '/artists?tab=permissions',
    hidden: (role) => role !== 'owner' && role !== 'admin',
  },
]

const VALID_KEYS = new Set(ARTISTS_TABS.map((t) => t.key))

interface Props {
  searchParams: Promise<Record<string, string | string[] | undefined>>
}

export default async function ArtistsPage({ searchParams }: Props) {
  const auth = await getAuthenticatedUser()
  if (!auth) redirect('/login')

  const supabase = await createClient()

  let plan: PlanTier = 'solo'
  const { data: sub } = await supabase
    .from('subscriptions')
    .select('plan_tier')
    .eq('studio_id', auth.studioId)
    .eq('status', 'active')
    .maybeSingle()
  if (sub?.plan_tier) plan = sub.plan_tier as PlanTier

  const role = auth.role as NavRole
  const params = await searchParams
  const rawTab = typeof params.tab === 'string' ? params.tab : undefined
  const activeKey = rawTab && VALID_KEYS.has(rawTab) ? rawTab : 'roster'

  const isOwner = role === 'owner'
  const isPro = plan === 'pro' || plan === 'enterprise'

  return (
    <PageShell>
      <PageHeader
        title="Team"
        description="Manage artists, schedules, and access permissions"
      />

      {/* Tab row */}
      <div className="mt-6">
        <PageTabs
          tabs={filterTabsForRole(ARTISTS_TABS, role)}
          activeKey={activeKey}
          currentPlan={plan}
          currentRole={role}
        />
      </div>

      {/* Tab content */}
      <div role="tabpanel" id={`tabpanel-${activeKey}`} className="flex flex-col flex-1 min-h-0 mt-2">
        <Suspense fallback={<div className="flex-1 animate-pulse bg-muted/20 rounded-xl min-h-[200px]" />}>
          {activeKey === 'roster' && (
            <div className="flex flex-col gap-4 flex-1 min-h-0">
              {/* Leaderboard — owner/admin only */}
              {(role === 'owner' || role === 'admin') && (
                <div className="pt-4">
                  <LeaderboardCard studioId={auth.studioId} />
                </div>
              )}
              <ArtistsRosterClient />
            </div>
          )}

          {activeKey === 'schedules' && (
            <SchedulesTabClient />
          )}

          {activeKey === 'guest-artists' && (
            hasFeature(plan, 'guest_artists')
              ? <GuestArtistsHub />
              : (
                <div className="flex flex-1 items-center justify-center p-8">
                  <UpgradeGatePageBlock
                    requiredPlan="pro"
                    feature="Guest Artists"
                    description="Invite guest artists, track their bookings, manage commission splits, and handle payouts. Upgrade to Pro to unlock guest artist management."
                  />
                </div>
              )
          )}

          {activeKey === 'permissions' && (
            <div className="py-4">
              <PermissionsMatrix isPro={isPro} canEdit={isOwner} />
            </div>
          )}
        </Suspense>
      </div>
    </PageShell>
  )
}

import type { Metadata } from 'next'
import { redirect } from 'next/navigation'
import { Suspense } from 'react'
import Link from 'next/link'
import { getAuthenticatedUser } from '@/lib/supabase/server'
import { listFlashEvents, type FlashEventFilter } from '@/lib/flash-events/queries'
import { FlashEventsListClient } from '@/components/flash-events/FlashEventsListClient'
import { Skeleton } from '@/components/ui/skeleton'
import { PageShell } from '@/components/shared/PageShell'
import { PageHeader } from '@/components/shared/PageHeader'
import { Button } from '@/components/ui/button'
import { Plus } from 'lucide-react'

export const metadata: Metadata = {
  title: 'Flash Events — InkOS',
}

interface Props {
  searchParams: Promise<Record<string, string | string[] | undefined>>
}

const VALID_STATUS_FILTERS = ['upcoming', 'draft', 'published', 'completed', 'cancelled', 'all'] as const
type ValidStatusFilter = (typeof VALID_STATUS_FILTERS)[number]

export default async function FlashEventsPage({ searchParams }: Props) {
  const auth = await getAuthenticatedUser()
  if (!auth) redirect('/login')

  const params = await searchParams
  const statusParam = typeof params.status === 'string' ? params.status : 'upcoming'
  const filter: ValidStatusFilter = VALID_STATUS_FILTERS.includes(statusParam as ValidStatusFilter)
    ? (statusParam as ValidStatusFilter)
    : 'upcoming'

  // Build filter: 'all' means no status filter
  const filterArg: FlashEventFilter = {}
  if (filter !== 'all') {
    filterArg.status = filter as NonNullable<FlashEventFilter['status']>
  }
  const events = await listFlashEvents(auth.studioId, filterArg).catch(() => [])

  const canCreate = ['owner', 'admin', 'receptionist'].includes(auth.role)

  return (
    <PageShell>
      <PageHeader
        title="Flash Events"
        description="One-day themed events with pre-set slots"
        actions={
          canCreate ? (
            <Button size="sm" render={<Link href="/flash-events/new" />}>
              <Plus className="h-4 w-4" />
              New event
            </Button>
          ) : undefined
        }
      />
      <div className="mt-6">
        <Suspense fallback={<FlashEventsListSkeleton />}>
          <FlashEventsListClient
            events={events}
            activeFilter={filter}
            studioId={auth.studioId}
            role={auth.role}
          />
        </Suspense>
      </div>
    </PageShell>
  )
}

function FlashEventsListSkeleton() {
  return (
    <div className="p-6 space-y-4">
      <Skeleton className="h-8 w-48" />
      <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3">
        {Array.from({ length: 6 }).map((_, i) => (
          <Skeleton key={i} className="h-52 rounded-xl" />
        ))}
      </div>
    </div>
  )
}

import type { Metadata } from 'next'
import { redirect } from 'next/navigation'
import { createClient } from '@/lib/supabase/server'
import { getActiveStudio, NoStudioMembershipError } from '@/lib/context/active-studio'
import { InboxClient } from '@/components/inbox/InboxClient'
import type { RichInboxItem, InboxItemType } from '@/components/inbox/InboxClient'
import type { TeamMember } from '@/components/inbox/AssignUserPicker'
import type { PlanTier } from '@/lib/billing/feature-gate'
import type { NavRole } from '@/components/app/sidebar/nav-config'

export const metadata: Metadata = {
  title: 'Inbox — InkOS',
}

export default async function InboxPage() {
  const supabase = await createClient()
  const {
    data: { user },
  } = await supabase.auth.getUser()

  if (!user) redirect('/login')

  let activeStudio: Awaited<ReturnType<typeof getActiveStudio>>
  try {
    activeStudio = await getActiveStudio()
  } catch (err) {
    if (err instanceof NoStudioMembershipError) redirect('/onboarding')
    redirect('/onboarding')
  }

  const { studioId, role, plan } = activeStudio
  const sevenDaysAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString()
  const oneDayAgo = new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString()

  // Fetch all data sources in parallel
  const [
    pendingBookingsRes,
    consentSubmissionsRes,
    waitlistRes,
    newClientsRes,
    assignmentsRes,
    membersRes,
    unreadConversationsRes,
  ] = await Promise.all([
    // 1. Pending bookings — include scheduled_at for urgency
    supabase
      .from('bookings')
      .select('id, created_at, scheduled_at, clients(first_name, last_name)')
      .eq('studio_id', studioId)
      .eq('status', 'pending')
      .eq('deposit_paid', false)
      .order('scheduled_at', { ascending: true })
      .limit(50),

    // 2. Bookings with consent required but not yet signed (last 7d)
    supabase
      .from('bookings')
      .select('id, client_id, created_at, scheduled_at, clients(first_name, last_name)')
      .eq('studio_id', studioId)
      .eq('consent_required', true)
      .is('consent_signed_at', null)
      .gte('created_at', sevenDaysAgo)
      .order('scheduled_at', { ascending: true })
      .limit(30),

    // 3. Waitlist entries (last 24h)
    supabase
      .from('waitlist_entries')
      .select('id, client_id, created_at, clients(first_name, last_name)')
      .eq('studio_id', studioId)
      .eq('status', 'active')
      .gte('created_at', oneDayAgo)
      .order('created_at', { ascending: false })
      .limit(20),

    // 4. New clients (last 7d)
    supabase
      .from('clients')
      .select('id, first_name, last_name, created_at')
      .eq('studio_id', studioId)
      .gte('created_at', sevenDaysAgo)
      .is('archived_at', null)
      .order('created_at', { ascending: false })
      .limit(10),

    // 5. Inbox assignments — active only (non-archived, non-resolved) with limit.
    //    S19 perf: previously pulled every assignment ever, including long-archived.
    supabase
      .from('inbox_assignments')
      .select('item_kind, item_id, assigned_to, snoozed_until, archived_at, resolved_at')
      .eq('studio_id', studioId)
      .is('archived_at', null)
      .is('resolved_at', null)
      .limit(500),

    // 6. Studio members for assignment picker
    supabase
      .from('studio_members')
      .select('user_id, role, profiles(full_name, avatar_url)')
      .eq('studio_id', studioId)
      .is('deactivated_at', null),

    // 7. Unread message conversations
    supabase
      .from('conversations')
      .select('id, client_id, display_name, last_message_preview, last_message_at, unread_count, channel')
      .eq('studio_id', studioId)
      .is('archived_at', null)
      .gt('unread_count', 0)
      .order('last_message_at', { ascending: false })
      .limit(50),
  ])

  // Build assignment map: key = `${kind}-${item_id}`
  type AssignmentState = {
    assignedTo: string | null
    snoozedUntil: string | null
    archivedAt: string | null
    resolvedAt: string | null
  }

  const assignmentMap = new Map<string, AssignmentState>()
  for (const a of assignmentsRes.data ?? []) {
    assignmentMap.set(`${a.item_kind}-${a.item_id}`, {
      assignedTo: a.assigned_to,
      snoozedUntil: a.snoozed_until,
      archivedAt: a.archived_at,
      resolvedAt: a.resolved_at,
    })
  }

  function getAssignment(kind: InboxItemType, itemId: string): AssignmentState {
    return assignmentMap.get(`${kind}-${itemId}`) ?? {
      assignedTo: null,
      snoozedUntil: null,
      archivedAt: null,
      resolvedAt: null,
    }
  }

  // Normalize into RichInboxItem[]
  const items: RichInboxItem[] = []

  // Pending bookings (deposit overdue)
  for (const booking of pendingBookingsRes.data ?? []) {
    const clientRow = Array.isArray(booking.clients) ? booking.clients[0] : booking.clients
    const clientName = clientRow
      ? `${clientRow.first_name}${clientRow.last_name ? ` ${clientRow.last_name}` : ''}`
      : 'Client'
    const a = getAssignment('deposit', booking.id)

    items.push({
      id: `booking-${booking.id}`,
      type: 'deposit' as InboxItemType,
      title: 'Deposit pending',
      subtitle: clientName,
      actionLabel: 'View booking',
      actionHref: `/bookings/${booking.id}`,
      timestamp: booking.created_at,
      scheduledAt: booking.scheduled_at,
      ...a,
    })
  }

  // Bookings with unsigned consent forms
  for (const booking of consentSubmissionsRes.data ?? []) {
    const clientRow = Array.isArray(booking.clients) ? booking.clients[0] : booking.clients
    const clientName = clientRow
      ? `${clientRow.first_name}${clientRow.last_name ? ` ${clientRow.last_name}` : ''}`
      : 'Client'
    const a = getAssignment('form', booking.id)

    items.push({
      id: `consent-${booking.id}`,
      type: 'form' as InboxItemType,
      title: 'Consent form unsigned',
      subtitle: clientName,
      actionLabel: 'View booking',
      actionHref: `/bookings/${booking.id}`,
      timestamp: booking.created_at,
      scheduledAt: booking.scheduled_at,
      ...a,
    })
  }

  // Waitlist entries
  for (const entry of waitlistRes.data ?? []) {
    const clientRow = Array.isArray(entry.clients) ? entry.clients[0] : entry.clients
    const clientName = clientRow
      ? `${clientRow.first_name}${clientRow.last_name ? ` ${clientRow.last_name}` : ''}`
      : 'Client'
    const a = getAssignment('waitlist', entry.id)

    items.push({
      id: `waitlist-${entry.id}`,
      type: 'waitlist' as InboxItemType,
      title: 'New waitlist signup',
      subtitle: clientName,
      actionLabel: 'View',
      actionHref: `/clients/${entry.client_id}`,
      timestamp: entry.created_at,
      scheduledAt: null,
      ...a,
    })
  }

  // New clients
  for (const client of newClientsRes.data ?? []) {
    const clientName = `${client.first_name}${client.last_name ? ` ${client.last_name}` : ''}`
    const a = getAssignment('client', client.id)

    items.push({
      id: `client-${client.id}`,
      type: 'client' as InboxItemType,
      title: 'New client',
      subtitle: clientName,
      actionLabel: 'View',
      actionHref: `/clients/${client.id}`,
      timestamp: client.created_at,
      scheduledAt: null,
      ...a,
    })
  }

  // Unread message conversations
  for (const conv of unreadConversationsRes.data ?? []) {
    const preview = conv.last_message_preview
      ? String(conv.last_message_preview).slice(0, 80)
      : 'New message'
    const clientId = conv.client_id as string | null
    const a = clientId ? getAssignment('client', clientId) : {
      assignedTo: null,
      snoozedUntil: null,
      archivedAt: null,
      resolvedAt: null,
    }

    items.push({
      id: `conv-${conv.id as string}`,
      type: 'unread-message' as InboxItemType,
      title: String(conv.display_name ?? 'Message'),
      subtitle: preview,
      actionLabel: 'Reply',
      actionHref: clientId ? `/clients/${clientId}?tab=comms` : '/inbox',
      timestamp: conv.last_message_at as string ?? new Date().toISOString(),
      scheduledAt: null,
      ...a,
    })
  }

  // Sort by timestamp descending
  items.sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime())

  // Build team members list for assignment picker
  const members: TeamMember[] = (membersRes.data ?? []).map((m) => {
    const profileRow = Array.isArray(m.profiles) ? m.profiles[0] : m.profiles
    return {
      userId: m.user_id,
      name: profileRow?.full_name ?? m.user_id,
      role: m.role,
      avatarUrl: profileRow?.avatar_url ?? null,
    }
  })

  return (
    <InboxClient
      items={items}
      members={members}
      currentUserId={user.id}
      currentPlan={plan as PlanTier}
      currentRole={role as NavRole}
    />
  )
}

import type { Metadata } from 'next'
