import type { PageTab } from '@/components/shared/PageTabs'
import type { PlanTier } from '@/lib/billing/feature-gate'
import type { NavRole } from '@/components/app/sidebar/nav-config'
import { PageShell } from '@/components/shared/PageShell'
import { PageHeader } from '@/components/shared/PageHeader'

export const metadata: Metadata = {
  title: 'Team — InkOS',
}

const ARTISTS_TABS: PageTab[] = [
  {
    key: 'roster',
    label: 'Roster',
    href: '/artists?tab=roster',
  },
  {
    key: 'schedules',
    label: 'Schedules',
    href: '/artists?tab=schedules',
    hidden: (role) => role === 'guest_artist',
  },
  {
    key: 'guest-artists',
    label: 'Guest Artists',
    href: '/artists?tab=guest-artists',
    gated: 'pro',
    hidden: (role) => role !== 'owner' && role !== 'admin',
  },
  {
    key: 'permissions',
    label: 'Permissions',
    href: '/artists?tab=permissions',
    hidden: (role) => role !== 'owner' && role !== 'admin',
  },
]

const VALID_KEYS = new Set(ARTISTS_TABS.map((t) => t.key))

interface Props {
  searchParams: Promise<Record<string, string | string[] | undefined>>
}

export default async function ArtistsPage({ searchParams }: Props) {
  const auth = await getAuthenticatedUser()
  if (!auth) redirect('/login')

  const supabase = await createClient()

  let plan: PlanTier = 'solo'
  const { data: sub } = await supabase
    .from('subscriptions')
    .select('plan_tier')
    .eq('studio_id', auth.studioId)
    .eq('status', 'active')
    .maybeSingle()
  if (sub?.plan_tier) plan = sub.plan_tier as PlanTier

  const role = auth.role as NavRole
  const params = await searchParams
  const rawTab = typeof params.tab === 'string' ? params.tab : undefined
  const activeKey = rawTab && VALID_KEYS.has(rawTab) ? rawTab : 'roster'

  const isOwner = role === 'owner'
  const isPro = plan === 'pro' || plan === 'enterprise'

  return (
    <PageShell>
      <PageHeader
        title="Team"
        description="Manage artists, schedules, and access permissions"
      />

      {/* Tab row */}
      <div className="mt-6">
        <PageTabs
          tabs={filterTabsForRole(ARTISTS_TABS, role)}
          activeKey={activeKey}
          currentPlan={plan}
          currentRole={role}
        />
      </div>

      {/* Tab content */}
      <div role="tabpanel" id={`tabpanel-${activeKey}`} className="flex flex-col flex-1 min-h-0 mt-2">
        <Suspense fallback={<div className="flex-1 animate-pulse bg-muted/20 rounded-xl min-h-[200px]" />}>
          {activeKey === 'roster' && (
            <div className="flex flex-col gap-4 flex-1 min-h-0">
              {/* Leaderboard — owner/admin only */}
              {(role === 'owner' || role === 'admin') && (
                <div className="pt-4">
                  <LeaderboardCard studioId={auth.studioId} />
                </div>
              )}
              <ArtistsRosterClient />
            </div>
          )}

          {activeKey === 'schedules' && (
            <SchedulesTabClient />
          )}

          {activeKey === 'guest-artists' && (
            hasFeature(plan, 'guest_artists')
              ? <GuestArtistsHub />
              : (
                <div className="flex flex-1 items-center justify-center p-8">
                  <UpgradeGatePageBlock
                    requiredPlan="pro"
                    feature="Guest Artists"
                    description="Invite guest artists, track their bookings, manage commission splits, and handle payouts. Upgrade to Pro to unlock guest artist management."
                  />
                </div>
              )
          )}

          {activeKey === 'permissions' && (
            <div className="py-4">
              <PermissionsMatrix isPro={isPro} canEdit={isOwner} />
            </div>
          )}
        </Suspense>
      </div>
    </PageShell>
  )
}

