type SidebarContextProps = {
  state: "expanded" | "collapsed"
  open: boolean
  setOpen: (open: boolean) => void
  openMobile: boolean
  setOpenMobile: (open: boolean) => void
  isMobile: boolean
  toggleSidebar: () => void
}

const SidebarContext = React.createContext<SidebarContextProps | null>(null)

function useSidebar() {
  const context = React.useContext(SidebarContext)
  if (!context) {
    throw new Error("useSidebar must be used within a SidebarProvider.")
  }

  return context
}

function SidebarProvider({
  defaultOpen = true,
  open: openProp,
  onOpenChange: setOpenProp,
  className,
  style,
  children,
  ...props
}: React.ComponentProps<"div"> & {
  defaultOpen?: boolean
  open?: boolean
  onOpenChange?: (open: boolean) => void
}) {
  const isMobile = useIsMobile()
  const [openMobile, setOpenMobile] = React.useState(false)

  // This is the internal state of the sidebar.
  // We use openProp and setOpenProp for control from outside the component.
  const [_open, _setOpen] = React.useState(defaultOpen)

  }, [role, locationCount, permissions])

  return (
    <Sidebar
      collapsible="icon"
      className={[
        'border-r border-sidebar-border',
        // Rust edge accent — barely-visible 1px gradient stripe on the right seam.
        // Fades in/out vertically so it reads as a brand signature, not a hard line.
        'relative after:pointer-events-none after:absolute after:right-0 after:top-0 after:h-full after:w-px',
        'after:bg-[linear-gradient(to_bottom,transparent_0%,oklch(58%_0.16_35/_0.12)_40%,oklch(58%_0.16_35/_0.12)_60%,transparent_100%)]',
      ].join(' ')}
    >
      {/* ── Brand header — minimal: logo + InkOS + Studio OS ─── */}
      <SidebarHeader className="border-b border-sidebar-border/60 px-3 py-2.5">
        <div className="flex items-center gap-2 group-data-[collapsible=icon]:justify-center">
          {studioLogoUrl ? (
            // eslint-disable-next-line @next/next/no-img-element
            <img
              src={studioLogoUrl}
              alt="InkOS"
              className="h-8 w-8 shrink-0 rounded-md object-cover"
            />
          ) : (
            /* InkOS brand mark — italic `i` in Onyx tile per brand book */
            <div className="flex h-8 w-8 shrink-0 items-center justify-center rounded-md bg-foreground text-background">
              <span className="font-serif-italic text-xl leading-none">i</span>
            </div>
          )}
          <span className="truncate text-[15px] font-bold tracking-tight text-sidebar-foreground group-data-[collapsible=icon]:hidden">
            InkOS
          </span>
        </div>
      </SidebarHeader>

      {/* ── Nav groups ────────────────────────────────────────── */}
      <SidebarContent className="gap-0 px-2 py-3">
        {navGroups.map((group, idx) => (
          <SidebarNavGroup
            key={group.label ?? '_unlabeled'}
            group={group}
            plan={plan}
            isFirst={idx === 0}
            dynamicBadges={dynamicBadges}
          />
        ))}

        {/* S22: Favorites */}
        <SidebarFavorites pinnedItems={pinnedItems} />
      </SidebarContent>
    </Sidebar>
  )
}

