  artists: ArtistMini[]
  canManage: boolean
}

// ── Lightbox ─────────────────────────────────────────────────────────────────

interface LightboxProps {
  item: PortfolioItemWithArtist
  styleTags: StyleTag[]
  onClose: () => void
  onPrev: (() => void) | null
  onNext: (() => void) | null
}

function Lightbox({ item, styleTags, onClose, onPrev, onNext }: LightboxProps) {
  return (
    <div
      className="fixed inset-0 z-50 bg-background/90 backdrop-blur-sm flex items-center justify-center"
      onClick={onClose}
      role="dialog"
      aria-modal="true"
      aria-label="Portfolio photo viewer"
    >
      <button
        type="button"
        className="absolute top-4 right-4 h-8 w-8 rounded-full bg-foreground/10 flex items-center justify-center text-foreground hover:bg-foreground/20 transition-colors"
        onClick={onClose}
        aria-label="Close"
      >
        <X className="h-4 w-4" />
      </button>

      <div
        className="relative max-w-3xl w-full mx-4 space-y-3"
        onClick={(e) => e.stopPropagation()}
      >
        {/* eslint-disable-next-line @next/next/no-img-element */}
        <img
          src={getPublicUrl(item.storage_path)}
          alt={item.caption ?? 'Portfolio photo'}
          className="w-full max-h-[75vh] object-contain rounded-xl"
        />

        <div className="space-y-1">
          <div className="flex items-center justify-between">
            <Link
              href={`/artists/${item.artist_id}?tab=portfolio`}
              className="text-sm font-medium hover:underline"
            >
              {item.artist.display_name}
            </Link>
            {item.is_featured && (
              <Badge variant="secondary" className="text-xs">Featured</Badge>
            )}
          </div>
          {item.caption && (
            <p className="text-sm text-muted-foreground">{item.caption}</p>
          )}
          {item.style_tag_ids.length > 0 && (
            <StyleTagChips tagIds={item.style_tag_ids} tags={styleTags} />
          )}
        </div>

        {/* Navigation */}
        <div className="flex justify-between pt-1">
          {onPrev ? (
            <Button size="sm" variant="outline" onClick={onPrev}>
              ← Previous
            </Button>
          ) : <div />}

